import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { ProductService } from '../../services/product.service';
import { Product, Category, Banner } from '../../models/product.model';

@Component({
  selector: 'app-landing',
  standalone: true,
  imports: [CommonModule, RouterLink],
  template: `
    <div class="container">
      <!-- Banners Section -->
      <section class="banners" *ngIf="banners.length > 0">
        <div class="banner" *ngFor="let banner of banners">
          <img [src]="banner.image" [alt]="banner.title" class="banner-img">
          <div class="banner-content">
            <h2>{{ banner.title }}</h2>
            <p>{{ banner.description }}</p>
            <span class="discount-badge" *ngIf="banner.discount_offer">
              {{ banner.discount_offer }}
            </span>
          </div>
        </div>
      </section>

      <!-- Categories Section - Horizontal Scrollable -->
      <section class="categories mt-4">
        <h2 class="text-center mb-3">Shop by Category</h2>
        <div class="category-scroll-container">
          <div class="category-scroll">
            <div class="category-item" *ngFor="let category of categories" [routerLink]="['/products']" [queryParams]="{category: category.id}">
              <div class="category-image-wrapper">
                <img [src]="category.image || 'assets/placeholder.jpg'" [alt]="category.display_name" class="category-img">
              </div>
              <h3 class="category-name">{{ category.display_name }}</h3>
            </div>
          </div>
        </div>
      </section>

      <!-- Featured Products -->
      <section class="featured-products mt-4">
        <h2 class="text-center mb-3">Featured Products</h2>
        <div class="grid">
          <div class="card" *ngFor="let product of featuredProducts" [routerLink]="['/products', product.id]">
            <img [src]="product.image" [alt]="product.name" class="card-img">
            <div class="card-body">
              <h3 class="card-title">{{ product.title }}</h3>
              <div class="price-section">
                <span class="price-original" *ngIf="product.discounted_price">₹{{ product.price }}</span>
                <span class="price">₹{{ product.final_price }}</span>
                <span class="discount-badge" *ngIf="product.discount_percentage > 0">
                  {{ product.discount_percentage }}% OFF
                </span>
              </div>
              <p class="card-text">{{ product.purity }}</p>
            </div>
          </div>
        </div>
      </section>
    </div>
  `,
  styles: [`
    .container {
      padding: 0;
      max-width: 100%;
    }

    h2 {
      color: var(--primary-purple);
      font-family: 'Playfair Display', serif;
      font-size: 2.5rem;
      margin-bottom: 2rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 2px;
    }

    .banners {
      margin: 2rem 0;
    }

    .banner {
      position: relative;
      border-radius: 12px;
      overflow: hidden;
      margin-bottom: 2rem;
      box-shadow: 0 8px 24px rgba(139, 58, 98, 0.15);
    }

    .banner-img {
      width: 100%;
      height: 400px;
      object-fit: cover;
    }

    .banner-content {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      background: linear-gradient(transparent, rgba(139, 58, 98, 0.95));
      color: white;
      padding: 2rem;
    }

    .banner-content h2 {
      color: white;
      margin-bottom: 0.5rem;
    }

    .discount-badge {
      background: linear-gradient(135deg, #4A7C59 0%, #5A9C69 100%);
      color: white;
      padding: 0.5rem 1rem;
      border-radius: 20px;
      font-weight: 600;
      display: inline-block;
      margin-top: 1rem;
      box-shadow: 0 4px 8px rgba(74, 124, 89, 0.3);
    }

    /* Full Grid Categories */
    .categories {
      background: linear-gradient(135deg, #8B3A62 0%, #A94B76 50%, #C77BA1 100%);
      padding: 4rem 2rem;
      margin: 0;
    }

    .categories h2 {
      color: white;
      text-align: center;
      margin-bottom: 3rem;
      text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
    }

    .category-scroll-container {
      max-width: 1400px;
      margin: 0 auto;
    }

    .category-scroll {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 2.5rem;
      padding: 0;
    }

    .category-item {
      text-align: center;
      cursor: pointer;
      transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
      padding: 1rem;
    }

    .category-item:hover {
      transform: translateY(-12px) scale(1.05);
    }

    .category-image-wrapper {
      width: 180px;
      height: 180px;
      border-radius: 50%;
      overflow: hidden;
      margin: 0 auto 1.25rem;
      background: white;
      border: 5px solid white;
      transition: all 0.4s ease;
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
      position: relative;
    }

    .category-image-wrapper::after {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: linear-gradient(135deg, rgba(74, 124, 89, 0.3) 0%, transparent 100%);
      opacity: 0;
      transition: opacity 0.3s ease;
    }

    .category-item:hover .category-image-wrapper {
      border-color: #4A7C59;
      box-shadow: 0 12px 32px rgba(74, 124, 89, 0.4);
      transform: rotate(5deg);
    }

    .category-item:hover .category-image-wrapper::after {
      opacity: 1;
    }

    .category-img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.4s ease;
    }

    .category-item:hover .category-img {
      transform: scale(1.1);
    }

